const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>s?new Date(s).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}):'—';
let requestedCount=12,emailPreview=null;
function syncTheme(){const dark=document.documentElement.dataset.theme==='dark',b=$('#theme-toggle');if(b){b.textContent=dark?'☀':'☾';b.title=b.ariaLabel=dark?'Switch to light mode':'Switch to dark mode';b.setAttribute('aria-pressed',String(dark));}const field=$('#theme-preference');if(field)field.value=window.relayTheme?.preference||'system';}
window.addEventListener('relay-theme',syncTheme);
function countInput(){return `<label class="search-count">Prospects<input name="searchTarget" type="number" min="1" max="1000" step="1" value="${esc(requestedCount)}" required></label>`;}
function requestedTarget(){const n=Number(requestedCount);if(!Number.isInteger(n)||n<1||n>1000)throw new Error('Choose 1–1,000 prospects');return n;}
const money=n=>'$'+Number(n||0).toFixed(2);
const safeLink=v=>{try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#';}catch{return '#';}};
const pill=s=>`<span class="pill">${esc(({approved:'Ready',target_review:'Preparing',analyzing:'Preparing',draft:'New',paused:'Limit reached',paused_provider:'Provider issue',budget_paused:'Budget reached'})[s]||s)}</span>`;
const labels={preparing:'Preparing email',pending:'Pending send',attention:'Needs attention',scheduled:'Scheduled',sending:'Sending',sent:'Sent',replied:'Replied',failed:'Send failed',check_sent:'Check delivery',stopped:'Stopped',not_sent:'Not sent'};
const groupLabels={all:'All prospects',pending:'Pending send',sent:'Emails sent',contacted:'Businesses contacted',followup:'Follow-up due',replied:'Businesses that replied',attention:'Needs attention'};
let data=null,view='prospects',filter='',statusFilter='all',dashboardGroup='sent',modalDraft=null,detailData=null;
let locationSelection=null,workspaceUnavailable=false,snapshotMode=null,lastSavedRefresh=0;
let notificationData={items:[],unread:0},notificationUnavailable=false;
let products=[],selectedProduct=new URLSearchParams(location.search).get('product')||sessionStorage.getItem('relay-product')||'',productDetailData=null;
let loadRequest=0,modalRequest=0,pageLoading=false;
const pendingButtons=new Map();
const buttonKey=b=>b.id||(b.form?b.form.id+':'+b.type:JSON.stringify(Object.entries(b.dataset).sort(([a],[z])=>a.localeCompare(z))));
function markBusy(b,entry){if(!entry.buttons.has(b))entry.buttons.set(b,{disabled:b.disabled,busy:b.getAttribute('aria-busy')});b.disabled=true;b.setAttribute('aria-busy','true');}
function beginBusy(b){if(!b)return ()=>{};const key=buttonKey(b),entry={buttons:new Map()};pendingButtons.set(key,entry);markBusy(b,entry);return ()=>{pendingButtons.delete(key);for(const [button,state]of entry.buttons){button.disabled=state.disabled;if(state.busy===null)button.removeAttribute('aria-busy');else button.setAttribute('aria-busy',state.busy);}if(data){renderProductSwitch();lockSavedControls();syncBusyButtons();syncTheme();}};}
function syncBusyButtons(){for(const b of document.querySelectorAll('button')){const entry=pendingButtons.get(buttonKey(b));if(entry)markBusy(b,entry);}}
let pageData={rows:[],counts:{},total:0,offset:0,hasMore:false},pageRequest=0,searchTimer;
const title=(heading,sub='',buttons='')=>`<div class="page-head"><div><h1>${heading}</h1>${sub?`<p>${sub}</p>`:''}</div><div class="actions">${buttons}</div></div>`;
const empty=(heading,sub)=>`<div class="empty"><h3>${heading}</h3><p>${sub}</p></div>`;
const input=(name,label,value,type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const customerTypeOptions={b2b:'B2B businesses',b2c:'B2C market / distribution partners',individuals:'Individual professionals / creators',agencies:'Agencies',startups:'Startups',other:'Other / describe below'};
function customerFields(s={}){return `<fieldset><legend>Customer types</legend><div class="form-grid">${Object.entries(customerTypeOptions).map(([key,label])=>`<label class="checkbox"><input type="checkbox" name="customerTypes" value="${key}" ${(s.customerTypes||[]).includes(key)?'checked':''}>${label}</label>`).join('')}</div></fieldset><label>Ideal customer<textarea name="customerDescription" rows="3" maxlength="8000" placeholder="For example: small video editing agencies, independent creators, or startups building consumer budgeting products">${esc(s.customerDescription||'')}</textarea></label><label>Targeting notes<textarea name="customerComments" rows="3" maxlength="8000" placeholder="Relevant workflows, company size, exclusions and what makes a prospect suitable">${esc(s.customerComments||'')}</textarea></label>`;}
const draftMessage=d=>d.body.trim()+(d.artifact?.trim()?'\n\nFree sample\n-----------\n'+d.artifact.trim():'');
const prospectIssues=d=>d.sendIssues||[];
function emailCheck(l){return !l.email?'Email not found':l.contact_status==='provider_verified'?'Work email verified (Apify)':l.contact_status==='publicly_sourced'?'Public email sourced (delivery unknown)':l.verification==='valid'?'Previously checked address':l.verification==='invalid'?'Invalid email':l.verification==='risky'?'Mailbox unconfirmed':l.verification==='unverified'?'Email check pending':'Recipient reviewed';}
function sendingNotice(){return !data.connections.sendingEnabled?'<details class="note warning"><summary>Sending unavailable</summary><button class="text-button" data-go="settings">Check connection</button></details>':'';}
function currentProduct(){return products.find(p=>p.id===selectedProduct);}
function profileReady(p=currentProduct()){return !!p&&p.state==='approved'&&p.approved_revision===p.revision;}
function workspaceNotice(){
 if(snapshotMode)return backupNotice();
 const issues=[...(data.pipeline?.issues||[])],p=currentProduct();
 if(p?.error&&!profileReady(p))issues.unshift({kind:'Product profile',error:p.error});
 if(data.pipeline?.providerBlock&&!issues.some(i=>/credit|billing/i.test(i.error||'')))issues.unshift({kind:'OpenAI',error:'Add API credits in Settings.'});
 return issues.length?`<details class="note warning workspace-notice"><summary>Search needs attention</summary><ul>${issues.map(i=>`<li><strong>${esc(i.company||i.kind?.replaceAll('_',' ')||'Search')}</strong>: ${esc(i.error||'Retry in Settings.')} ${i.id&&['failed','paused_provider'].includes(i.state)?`<button data-retry="${esc(i.id)}">Retry</button>`:''}</li>`).join('')}</ul></details>`:'';
}

async function api(path,payload){if(snapshotMode&&payload!==undefined&&!['/api/login','/api/logout'].includes(path))throw new Error('Saved records are read only while the database is unavailable.');if(selectedProduct&&!/^\/api\/(products|notifications|outreach|openai|session|login|logout)(?:[/?]|$)/.test(path))path+=(path.includes('?')?'&':'?')+'product='+encodeURIComponent(selectedProduct);const r=await fetch(path,{method:payload===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Requested-With':'Prepyr'},...(payload===undefined?{}:{body:JSON.stringify(payload)})});const value=await r.json();if(value.availability?.readOnly)snapshotMode=value.availability;if(r.status===401){$('#app').hidden=true;$('#login').hidden=false;}if(!r.ok){const error=new Error(value.error||'Request failed');error.code=value.code;error.status=r.status;throw error;}return value;}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,7000);}
async function refreshNotifications(){try{const feed=await api('/api/notifications');notificationData={items:feed.items||[],unread:feed.unread||0};notificationUnavailable=false;}catch{notificationUnavailable=true;}renderNotifications();}
function positionNotifications(){const panel=$('#notification-panel');if(panel&&!panel.hidden){const bottom=$('#notification-toggle').getBoundingClientRect().bottom;panel.style.setProperty('--notification-top',Math.max(8,bottom+8)+'px');$('#notification-list').style.maxHeight=Math.min(520,Math.max(120,window.innerHeight-bottom-90))+'px';}}
window.addEventListener('resize',positionNotifications);
function renderNotifications(){const badge=$('#notification-count');if(!badge)return;badge.hidden=!notificationData.unread;badge.textContent=notificationData.unread>99?'99+':String(notificationData.unread);$('#notification-toggle').setAttribute('aria-label',`Notifications, ${notificationData.unread} unread`);$('#notifications-read-all').disabled=notificationUnavailable||!!snapshotMode||!notificationData.unread;positionNotifications();$('#notification-list').innerHTML=notificationUnavailable?'<p class="notification-empty">Notifications are temporarily unavailable. Try refreshing.</p>':notificationData.items.length?notificationData.items.map(n=>`<button class="notification-item ${n.read_at?'':'unread'}" data-notification="${esc(n.id)}"><strong>${esc(n.title)}</strong>${n.body?`<span>${esc(n.body.length>100?n.body.slice(0,97)+'…':n.body)}</span>`:''}<small>${esc(n.workspace_name)} · ${date(n.created_at)}</small></button>`).join(''):'<p class="notification-empty">No notifications.</p>';}
document.addEventListener('click',e=>{if(!e.target.closest('.notification-center')&&$('#notification-panel')){$('#notification-panel').hidden=true;$('#notification-toggle').setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#notification-panel')&&!$('#notification-panel').hidden){$('#notification-panel').hidden=true;$('#notification-toggle').setAttribute('aria-expanded','false');$('#notification-toggle').focus();}});
async function fetchPage(offset=0){const seq=++pageRequest,workspace=selectedProduct,currentView=view;const group=view==='dashboard'?dashboardGroup:statusFilter;const result=await api('/api/prospects?'+new URLSearchParams({group,q:filter,offset:String(offset)}));if(seq!==pageRequest||workspace!==selectedProduct||currentView!==view)return false;pageData=result;return true;}
async function showPage(offset=0){pageLoading=true;render();const request=fetchPage(offset),seq=pageRequest;try{if(await request){pageLoading=false;render();}}catch(error){if(seq!==pageRequest)return;pageLoading=false;pageData={...pageData,rows:[],total:0,offset:0,hasMore:false};render();throw error;}}
async function navigate(nextView){
 ++loadRequest;++pageRequest;++modalRequest;view=nextView;filter='';statusFilter='all';pageLoading=false;clearTimeout(searchTimer);if($('#modal').open)$('#modal').close();modalDraft=null;
 if(view==='settings'){render();return;}
 if(view==='products'){
  const workspace=selectedProduct;productDetailData=null;render();if(!workspace)return;
  const seq=loadRequest;try{const detail=await api('/api/products/'+workspace);if(seq!==loadRequest||workspace!==selectedProduct||view!=='products')return;productDetailData=detail;render();}catch(error){if(seq!==loadRequest||workspace!==selectedProduct||view!=='products')return;productDetailData={error:error.message};render();throw error;}return;
 }
 await showPage();
}
async function load(){
 const seq=++loadRequest;
 await api('/api/session');if(seq!==loadRequest)return;
 $('#login').hidden=true;$('#app').hidden=false;
 const [list]=await Promise.all([api('/api/products').catch(()=>({products:[]})),refreshNotifications()]);if(seq!==loadRequest)return;products=list.products||[];if(selectedProduct&&!products.some(p=>p.id===selectedProduct)){selectedProduct='';sessionStorage.removeItem('relay-product');}
 try{const [next,,detail]=await Promise.all([api('/api/dashboard?summary=1'),['prospects','dashboard'].includes(view)?fetchPage(pageData.offset):Promise.resolve(),view==='products'&&selectedProduct?api('/api/products/'+selectedProduct):Promise.resolve(null)]);if(seq!==loadRequest)return;if(detail)productDetailData=detail;snapshotMode=next.availability?.readOnly?next.availability:null;if(snapshotMode)lastSavedRefresh=Date.now();data=next;pageLoading=false;workspaceUnavailable=false;render();}
 catch(error){if(seq!==loadRequest)return;if(error.status===401)throw error;if(data){pageLoading=false;toast('Could not refresh. Your prospects are still available.');return;}pageRequest++;pageLoading=false;workspaceUnavailable=true;data=null;pageData={rows:[],counts:{},total:0,offset:0,hasMore:false};if($('#modal').open)$('#modal').close();$('#breadcrumb').textContent='Workspace';$('#content').innerHTML=empty('Workspace data is temporarily unavailable',esc(error.message))+'<button data-reload>Try again</button>';}
}
async function action(path,payload={},message='Saved'){const result=await api(path,payload);toast(result.message||message);await load();return result;}
function rowStatus(row){if(row.email_status==='preparing'){if(row.research_job_state==='paused_provider')return /credit_balance_exhausted|insufficient_quota|billing_hard_limit_reached/.test(row.research_job_error||'')?'OpenAI credits exhausted':'Provider needs attention';if(row.research_job_state==='failed')return 'Research needs attention';if(row.research_job_state==='uncertain')return 'Research outcome needs review';if(row.research_job_state==='paused')return /Daily/.test(row.research_job_error||'')?'Daily research limit reached':'Research limit reached';if(row.research_job_state==='pending')return 'Research queued';}if(row.inbound_classification==='bounce')return 'Bounced';if(row.inbound_classification==='optout')return 'Unsubscribed';if(row.inbound_classification==='automatic')return 'Automatic reply received';if(row.inbound_classification==='reply')return row.email_status==='attention'?'Reply received ? Needs attention':'Reply received';const stages={contact_search:'Finding public contact',contact_extract:'Reviewing public contact',business_research:'Researching business',business_research_refine:'Deepening research',solution_design:'Designing solution',draft_generate:'Writing email',draft_assess:'Checking personalization'};return row.email_status==='preparing'?(stages[row.research_stage]||'Research queued'):labels[row.email_status]||'Preparing email';}
function fitSummary(l){try{const fit=JSON.parse(l.dossier||'{}').productFit;return fit?.observedWorkflow?'<small>'+esc(fit.observedWorkflow)+'</small>':'';}catch{return '';}}
function prospectLink(l){
 let contact={};try{contact=JSON.parse(l.contact_evidence||'{}')||{};}catch{}
 const urls=[contact.profileUrl,l.source_url,contact.sourceUrl].filter(Boolean);
 const profile=urls.find(value=>{try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password&&/(^|\.)linkedin\.com$/i.test(u.hostname)&&/^\/in\/[^/]+/.test(u.pathname);}catch{return false;}});
 const url=profile||[l.website,l.source_url,contact.sourceUrl].find(value=>safeLink(value)!=='#');
 return url?`<a href="${safeLink(url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc((profile?'LinkedIn profile':url===l.website?'Website':'Source')+' for '+(l.contact_name||l.company))}">${profile?'LinkedIn':url===l.website?'Website':'Source'} ↗</a>`:'<span class="quiet">—</span>';
}
function prospectTable(rows,emails=false){if(pageLoading)return '<div class="empty" role="status" aria-busy="true">Loading prospects…</div>';return rows.length?`<div class="table-wrap"><table><thead><tr><th>Prospect</th><th>Profile</th><th>Email</th><th>Status</th>${emails?'<th>Sent</th>':''}<th></th><th><span class="sr-only">Delete</span></th></tr></thead><tbody>${rows.map(l=>`<tr><td><strong>${esc(l.company)}</strong><small>${esc([l.city,l.country].filter(Boolean).join(', '))}</small>${selectedProduct?fitSummary(l):''}${emails?`<small>${esc(l.draft_subject)}</small>`:''}</td><td class="profile-cell">${prospectLink(l)}</td><td class="email-cell">${esc(l.email||'Not found')}</td><td><span class="pill status-${esc(l.email_status)}">${esc(rowStatus(l))}</span>${l.draft_kind==='followup'&&l.next_followup_at?`<small>Due ${date(l.next_followup_at)}</small>`:''}</td>${emails?`<td>${date(l.sent_at)}</td>`:''}<td><button data-open="${esc(l.id)}" ${l.draft_id?`data-email="${esc(l.draft_id)}"`:''}>${l.draft_kind==='followup'&&['pending','approved','failed'].includes(l.draft_status)?'Open Follow Up':l.draft_kind==='reply'&&['pending','approved','failed'].includes(l.draft_status)?'Open Reply':l.draft_id?'Open email':'Open prospect'}</button></td><td class="delete-cell"><button class="delete-prospect" data-delete-prospect="${esc(l.id)}" aria-label="Delete ${esc(l.company)}" title="Delete prospect" ${snapshotMode?'disabled':''}>×</button></td></tr>`).join('')}</tbody></table></div>`:empty('No emails yet.','Search for prospects to get started.');}

function pagination(){return `<div class="pagination"><span>${pageData.total?`${pageData.offset+1}–${pageData.offset+pageData.rows.length} of ${pageData.total}`:'0 results'}</span><button data-page="${Math.max(0,pageData.offset-50)}" ${pageData.offset?'':'disabled'}>Previous</button><button data-page="${pageData.offset+50}" ${pageData.hasMore?'':'disabled'}>Next</button></div>`;}
function searchProgress(){const c=data.metrics?.campaign||{},target=Number(c.target||12),qualified=Number(c.qualified||0),percent=Math.min(100,Math.floor(qualified/target*100));if(!c.id&&c.state!=='profiling')return '';return `<section class="panel search-progress" aria-label="Search progress"><div class="search-progress-heading"><strong>${percent}% · ${qualified} / ${target} prospects</strong><span class="quiet">${esc(({profiling:'Preparing',researching:'Researching',complete:'Complete',stopped:'Stopped',research_limit:'Research limit',search_limit:'Search limit'})[c.state]||'Searching')}</span>${c.canStop?`<button data-stop-search="${esc(c.id||'')}">Stop search</button>`:''}</div><progress aria-label="Qualified prospects" max="100" value="${percent}"></progress><details><summary>Search details</summary><p>${percent}% of the requested prospects have qualified emails drafted.</p><p>${Number(c.candidates||0)} candidates · ${Number(c.attempts||0)} researched · ${Number(c.rejected||0)} rejected</p></details></section>`;}
function prospects(){return title('Prospects')+`<div class="location-toolbar">${locationPicker()}${countInput()}<button class="primary" data-action="discover">Search prospects</button></div>${searchProgress()}<div class="filter-bar"><input id="search" type="search" placeholder="Search prospects" value="${esc(filter)}"><select id="status-filter" aria-label="Filter prospects">${Object.entries(groupLabels).filter(([key])=>!['sent','attention'].includes(key)).map(([key,label])=>`<option value="${key}" ${key===statusFilter?'selected':''}>${label}</option>`).join('')}</select></div>`+prospectTable(pageData.rows)+pagination();}

function dashboard(){const c=pageData.counts||{};return title('Dashboard')+`<div class="dashboard-cards">${['pending','sent','contacted','followup','replied'].map(key=>`<button class="metric ${dashboardGroup===key?'selected':''}" data-group="${key}" aria-pressed="${dashboardGroup===key}"><span>${groupLabels[key]}</span><strong>${Number(c[key]||0)}</strong></button>`).join('')}</div><section class="dashboard-details"><h2>${groupLabels[dashboardGroup]}</h2>${prospectTable(pageData.rows,dashboardGroup==='sent')}${pagination()}</section>`;}
function budgetHtml(){const b=data.budgets.find(b=>b.provider==='openai')||{};return `<div class="connection"><strong>OpenAI — all discovery and research</strong><span>${money(b.committed)} / ${money(data.settings.openaiBudget)}</span></div>`;}
function chosenLocations(){
 const country=$('#country-filter')?.value,place=$('#place-filter')?.value;
 if(country==='saved'||country===undefined)return locationSelection||data.settings.locationIds||['worldwide'];
 return country?[place||country]:['worldwide'];
}
function locationPicker(){
 const selected=locationSelection||data.settings.locationIds||['worldwide'],options=data.locationOptions||[],item=options.find(o=>o.id===selected[0]);
 const legacy=selected.length>1||selected[0]?.startsWith('region:'),country=legacy?'saved':item?.country?'country:'+item.country:selected[0]?.startsWith('country:')?selected[0]:'';
 const countries=options.filter(o=>o.group==='Countries').sort((a,b)=>a.label.localeCompare(b.label));
 const local=options.filter(o=>o.country&&'country:'+o.country===country&&o.group!=='Countries').sort((a,b)=>a.label.localeCompare(b.label));
 return `<div class="location-filters"><label>Country<select id="country-filter"><option value="">Worldwide</option>${legacy?'<option value="saved" selected>Saved locations</option>':''}${countries.map(o=>`<option value="${esc(o.id)}" ${country===o.id?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label><label>City / region<select id="place-filter" ${!country||legacy?'disabled':''}><option value="">${country&&!legacy?'Entire country':'Select a country first'}</option>${['States / regions','Cities'].map(group=>{const entries=local.filter(o=>o.group===group);return entries.length?`<optgroup label="${esc(group)}">${entries.map(o=>`<option value="${esc(o.id)}" ${selected.includes(o.id)?'selected':''}>${esc(o.label)}</option>`).join('')}</optgroup>`:'';}).join('')}</select></label></div>`;
}
async function saveLocations(){const ids=chosenLocations();if(!ids.length)throw new Error('Select at least one location.');const r=await api('/api/settings/locations',{locationIds:ids});if(r.settings)data.settings=r.settings;locationSelection=null;return r;}

function activity(){return `<details class="panel"><summary>Activity & costs</summary><div class="spaced">${budgetHtml()}</div><div class="actions spaced">${data.pipeline?.providerBlock?'<button data-billing-updated>I updated OpenAI billing</button>':''}<a href="/api/export${selectedProduct?'?product='+encodeURIComponent(selectedProduct):''}" download>Export records</a></div><details><summary>Task history</summary>${data.jobs.map(j=>`<div class="list-row"><div><strong>${esc(j.company||'Prospect search')}</strong><small>${esc(j.kind)} · ${esc(j.error||date(j.created_at))}</small></div><div>${pill(j.state)}${['failed','paused_provider'].includes(j.state)?`<button data-retry="${j.id}">Retry</button>`:''}</div></div>`).join('')||'<p>No tasks yet.</p>'}</details><details><summary>Search history</summary>${data.runs.map(r=>{const c=JSON.parse(r.campaign);return `<div class="list-row"><div>${esc(c.query)} · ${esc(c.location)}<small>${r.imported||0} businesses · ${r.held||0} need review · ${esc(r.error||date(r.created_at))}</small></div>${pill(r.state)}</div>`;}).join('')||'<p>No searches yet.</p>'}</details><details><summary>Event log</summary>${data.events.map(e=>`<p><small>${date(e.created_at)}</small><br>${esc(e.detail)}</p>`).join('')}</details></details>`;}
function earlierDraftsHtml(){const drafts=data.reviewDrafts||[];return drafts.length?`<details class="panel"><summary>Earlier drafts to reassess (${drafts.length})</summary><p>Targeting changed. Search to refresh the profile, then open an earlier draft and choose Improve this email.</p>${drafts.map(d=>`<div class="list-row"><div><strong>${esc(d.company)}</strong><small>${esc(d.subject)}</small></div><button data-open="${esc(d.lead_id)}" data-email="${esc(d.id)}">Review earlier draft</button></div>`).join('')}</details>`:'';}
function settingsPage(){const s=data.settings,c=data.connections;return title('Settings')+`<section class="panel appearance"><label>Appearance<select id="theme-preference"><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></label></section><details class="panel"><summary>Sender</summary><form id="sender-form"><div class="form-grid">${input('senderName','Name',s.senderName)}${selectedProduct?input('senderEmail','Email',c.sender,'email'):''}</div><button type="submit">Save</button><p id="sender-save-status" role="status"></p></form></details><details class="panel"><summary>Locations</summary><form id="locations-form">${locationPicker()}<button type="submit">Save</button></form></details><form id="settings-form" class="panel"><details><summary>Targeting & offer</summary>${customerFields(s)}<label>What you offer<textarea name="offerContext">${esc(s.offerContext)}</textarea></label><label>Free offer<textarea name="freeOffer" maxlength="1200">${esc(s.freeOffer||'')}</textarea></label><label>Portfolio & pricing<textarea name="portfolio">${esc(s.portfolio)}</textarea></label></details><details><summary>Search & budgets</summary><label>Sources<select name="discoveryProvider"><option value="openai" ${s.discoveryProvider!=='hybrid'?'selected':''}>Web</option><option value="hybrid" ${s.discoveryProvider==='hybrid'?'selected':''}>LinkedIn + web</option></select></label><label class="checkbox"><input name="allowWorkEmailEnrichment" type="checkbox" ${s.allowWorkEmailEnrichment?'checked':''}>Verified work-email enrichment</label><div class="form-grid">${[['openaiBudget','OpenAI / month ($)',50],['apifyBudget','Apify / month ($)',50],['apifyRunCap','Apify / run ($)',2],['discoveryResults','Candidates per batch',10]].map(([key,label,max])=>input(key,label,s[key],'number',`min="${key==='discoveryResults'?1:0.1}" max="${max}" step="${key==='discoveryResults'?1:0.1}"`)).join('')}</div></details><details><summary>Follow-ups & sending</summary>${input('followupDays','Follow-up days',s.followupDays.join(', '))}<div class="form-grid">${input('sendStartHour','Sending starts',s.sendStartHour,'number','min="0" max="23"')}${input('sendEndHour','Sending ends',s.sendEndHour,'number','min="1" max="24"')}</div><label class="checkbox"><input name="sendWeekends" type="checkbox" ${s.sendWeekends?'checked':''}>Send on weekends</label><label class="checkbox"><input name="providerPolicyConfirmed" type="checkbox" ${s.providerPolicyConfirmed?'checked':''}>My email service permits these emails</label></details><button type="submit" class="spaced">Save</button></form><details class="panel"><summary>Connections</summary>${[['OpenAI','openai'],['Apify','apify'],['Gmail','gmail'],['Telegram','telegram']].map(([label,key])=>`<div class="connection"><span>${label}</span>${pill(c[key]?'Connected':'Missing')}</div>`).join('')}<button data-action="check">Check</button><div id="connection-results"></div></details>${earlierDraftsHtml()}${activity()}<details class="panel"><summary>Import</summary><button data-action="import">Import prospects</button></details>`;}

function backupNotice(){return snapshotMode?`<div class="note warning" role="status">Saved copy from ${esc(date(snapshotMode.capturedAt))}. Read only while the database is unavailable.</div>`:'';}
function lockSavedControls(){if(!snapshotMode)return;document.querySelectorAll('#content form input,#content form textarea,#content form select,#content form button,#content [data-action],#content [data-retry],#content [name="locationIds"],#modal-content input,#modal-content textarea,#modal-content select,#modal-content button:not([data-open])').forEach(el=>el.disabled=true);}
function render(){if(!data)return;const names={prospects:'Prospects',dashboard:'Dashboard',settings:'Settings',products:'Products'};$('#breadcrumb').textContent=names[view];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=workspaceNotice()+({prospects,dashboard,settings:settingsPage,products:productsPage}[view])();renderProductSwitch();lockSavedControls();syncBusyButtons();syncTheme();}
function openModal(html){modalRequest++;$('#modal-content').innerHTML=backupNotice()+html;lockSavedControls();if(!$('#modal').open)$('#modal').showModal();}
$('#modal').addEventListener('close',()=>{modalRequest++;modalDraft=null;});
$('#modal').addEventListener('cancel',()=>{modalRequest++;modalDraft=null;});
function leadForm(l){return `<form id="lead-form" data-id="${l.id}"><div class="form-grid">${input('email','Email',l.email||'','email')}${input('contact_name','Contact name',l.contact_name)}<label>Contact permission<select name="eligibility">${['pending','eligible','ineligible'].map(x=>`<option value="${x}" ${l.eligibility===x?'selected':''}>${{pending:'Not recorded',eligible:'Can contact',ineligible:'Do not contact'}[x]}</option>`).join('')}</select><label>Contact basis<textarea name="eligibility_note">${esc(l.eligibility_note)}</textarea></label><label>Email check notes<textarea name="verification_note">${esc(l.verification_note)}</textarea></label></div><label class="checkbox"><input type="checkbox" name="manual" ${l.verification==='manual'?'checked':''}>I reviewed this public business address (delivery unknown).</label><button type="submit">Save contact</button></form>`;}
async function openProspect(id,draftId){modalDraft=null;openModal('<div role="status" aria-busy="true">Loading email and research…</div>');const seq=modalRequest,workspace=selectedProduct;try{const detail=await api('/api/prospects/'+encodeURIComponent(id));if(seq!==modalRequest||workspace!==selectedProduct||!$('#modal').open)return;detailData=detail;const {lead:l,drafts}=detailData;const d=drafts.find(x=>x.id===draftId)||drafts.find(x=>['pending','approved','failed','sending','uncertain'].includes(x.status))||drafts[0];if(d){await draftModal(d.id);return;}openModal(`<h2>${esc(l.company)}</h2><p>Research is preparing this business for review.</p>${contactEvidenceHtml(l)}<details><summary>Contact details</summary>${leadForm(l)}</details>`);}catch(error){if(seq!==modalRequest||workspace!==selectedProduct||!$('#modal').open)return;openModal('<h2>Email unavailable</h2><p>'+esc(error.message)+'</p><button data-open="'+esc(id)+'"'+(draftId?' data-email="'+esc(draftId)+'"':'')+'>Try again</button>');throw error;}}
function intelligenceHtml(l){let d={};try{d=JSON.parse(l.dossier||'{}');}catch{}return d.businessSummary?`<p><strong>Business</strong> · ${esc(d.businessSummary)}</p>${d.productFit?`<h3>Why this customer fits</h3><p><strong>Observed workflow</strong> · ${esc(d.productFit.observedWorkflow)}</p><p><strong>Matching product capability</strong> · ${esc(d.productFit.productCapability)}</p><p>${esc(d.productFit.whyRelevant)}</p><p><a href="${safeLink(d.productFit.sourceUrl)}" target="_blank" rel="noopener">Workflow evidence</a>: ${esc(d.productFit.excerpt)}</p>`:`<p><strong>Opportunity hypothesis</strong> · ${esc(d.opportunity)}</p>`}<p><strong>Unknowns</strong> · ${esc((d.unknowns||[]).join('; '))}</p>`:'';}

function contactEvidenceHtml(l){let c={};try{c=JSON.parse(l.contact_evidence||'{}');}catch{}if(c.status==='provider_verified')return `<p>Professional work email verified through Apify · ${esc(date(c.observedAt))}</p><p><a href="${safeLink(c.sourceUrl)}" target="_blank" rel="noopener">Verification run</a> · <a href="${safeLink(c.profileUrl)}" target="_blank" rel="noopener">Professional profile</a></p><p>${esc(c.reason)}</p><p class="quiet">Provider evidence, not a published email citation. Verification does not guarantee future delivery.</p>`;return c.sourceUrl?`<p>Public contact: <a href="${safeLink(c.sourceUrl)}" target="_blank" rel="noopener">Source</a> · ${esc(c.status)} · Delivery unknown</p><p>${esc(c.excerpt||c.reason)}</p>`: '<p class="quiet">Public email source needs review. An email address is not proof of mailbox delivery.</p>';}
function historyHtml(){return (detailData.messages||[]).length?detailData.messages.map(m=>`<details><summary>${m.direction==='outbound'?'Sent':'Received'} · ${date(m.created_at)} · ${esc(m.subject)}</summary><div class="pre">${esc(m.body)}</div></details>`).join(''):'<p>No emails sent or received yet.</p>';}
function sendExplanation(d,l){return `<p class="quiet send-explanation">${d.kind==='followup'&&Date.parse(l.next_followup_at)>Date.now()?'Approval saves your edits and schedules this follow-up for its due date.':'Send saves your edits, confirms this recipient can be contacted, and sends this email through Gmail.'}</p>`;}
function followupOrdinal(d,l){if(d.status!=='sent')return Math.min(3,Number(l.followup_count||0)+1);const sent=detailData.drafts.filter(x=>x.kind==='followup'&&x.status==='sent').sort((a,b)=>a.created_at.localeCompare(b.created_at)||a.id.localeCompare(b.id));return sent.findIndex(x=>x.id===d.id)+1;}
function renderEmailPreview(preview,message=preview.message||preview.body||''){
 const box=$('#email-preview');if(!box)return;box.replaceChildren();
 const text=document.createElement('div');text.className='email-message';
 const product=preview.product,name=product?.name?.trim(),url=safeLink(product?.website);
 const escaped=name?.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
 const pattern=name&&url!=='#'?new RegExp(`(?<![\\p{L}\\p{N}_])${escaped}(?![\\p{L}\\p{N}_])`,'giu'):null;
 const parts=String(message).split(/(https?:\/\/[^\s<>]+|www\.[^\s<>]+|[\w.+-]+@[\w.-]+\.[a-z]{2,})/gi);
 parts.forEach((part,index)=>{
  if(!pattern||index%2){text.append(document.createTextNode(part));return;}
  let cursor=0;for(const match of part.matchAll(pattern)){
   text.append(document.createTextNode(part.slice(cursor,match.index)));const a=document.createElement('a');a.href=product.website;a.textContent=match[0];a.target='_blank';a.rel='noopener noreferrer';text.append(a);cursor=match.index+match[0].length;
  }text.append(document.createTextNode(part.slice(cursor)));
 });
 box.append(text);if(preview.unsubscribeUrl&&safeLink(preview.unsubscribeUrl)!=='#'){const footer=document.createElement('p'),a=document.createElement('a');a.href=preview.unsubscribeUrl;a.textContent='Unsubscribe';a.target='_blank';a.rel='noopener noreferrer';footer.className='email-footer';footer.append(a);box.append(footer);}
}
async function draftModal(id){const d=detailData?.drafts.find(x=>x.id===id),l=detailData?.lead;if(!d||!l)return;modalDraft=id;emailPreview=null;const editable=!snapshotMode&&['pending','failed'].includes(d.status),issues=prospectIssues(d);const status={pending:'Pending send',approved:'Scheduled',failed:'Send failed',uncertain:'Check delivery',sending:'Sending',sent:'Sent',rejected:'Not sent',cancelled:'Not sent'}[d.status]||d.status;
 openModal(`<div class="simple-review"><h2>${esc(l.company)}</h2><p>${esc(l.email||'Email not found')} · ${esc(status)}</p>${d.kind==='followup'?`<p class="note">Follow-up ${followupOrdinal(d,l)} of 3 - ${d.status==='sent'?'Sent '+date(d.updated_at):'Due '+date(l.next_followup_at||d.send_after)}. ${Date.parse(l.next_followup_at||d.send_after)>Date.now()?'Approval schedules it for the due date; it will not send early.':'Awaiting your Send approval.'}</p>`:''}${editable?sendingNotice():''}${d.error?`<p class="note error">${esc(d.error)}</p>`:''}${issues.length&&editable?`<p class="note warning">${esc(issues[0])}</p>`:''}<form id="draft-form" data-id="${id}" data-version="${d.version}"><label>Subject<input name="subject" value="${esc(d.subject)}" ${editable?'':'disabled'}></label><div id="email-preview" class="email-rendered" aria-label="Email message">Loading email…</div><details class="email-editor"><summary>${editable?'Edit email':'Plain text'}</summary><label>Email<textarea name="body" rows="8" ${editable?'':'disabled'}>${esc(draftMessage(d))}</textarea></label></details>${editable?'<button type="submit">Save changes</button>':''}</form><details><summary>Research & contact details</summary><p>${esc(emailCheck(l))}</p><p>${esc(l.verification_note)}</p>${contactEvidenceHtml(l)}${intelligenceHtml(l)}<p>${esc(d.rationale)}</p>${JSON.parse(d.evidence).map(x=>`<p>${esc(x.observation)} <a href="${safeLink(x.url)}" target="_blank" rel="noopener">Source</a></p>`).join('')}${JSON.parse(d.warnings).map(w=>`<p>${esc(w)}</p>`).join('')}<details><summary>Edit contact</summary>${leadForm(l)}</details>${editable?`<button data-rewrite="${id}">Improve this email</button>`:''}<button class="danger" data-suppress="${l.id}">Stop contacting this business</button></details><details><summary>Email history</summary>${historyHtml()}</details><div class="modal-actions">${editable?`<button data-reject="${id}">Discard email</button><button class="primary" data-send="${id}" ${data.connections.sendingEnabled&&!issues.length?'':'disabled'}>${d.kind==='followup'&&Date.parse(l.next_followup_at)>Date.now()?'Approve follow-up':'Send'}</button>`:''}${['sending','uncertain'].includes(d.status)?`<button data-reconcile="${id}">Check delivery</button>`:''}</div></div>`);
 try{const p=await api(`/api/drafts/${id}/preview`);if(modalDraft===id&&$('#email-preview')){emailPreview=p;renderEmailPreview(p);}}catch(e){toast(e.message);}
}
function importModal(){modalDraft=null;openModal(`<h2>Import prospects</h2><form id="import-form"><label>Business records (JSON)<textarea name="records" rows="12" required></textarea></label><button type="submit">Import</button></form>`);}
async function saveEmail(d){const form=$('#draft-form');const subject=form.elements.namedItem('subject').value,body=form.elements.namedItem('body').value;if(subject===d.subject&&body===draftMessage(d))return d.version;await api(`/api/drafts/${d.id}/edit`,{version:d.version,subject,body,artifact:''});d.subject=subject;d.body=body;d.artifact='';d.version++;form.dataset.version=d.version;return d.version;}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled||(b.type==='submit'&&b.form)||pendingButtons.has(buttonKey(b)))return;const done=['close-modal','notification-toggle'].includes(b.id)?()=>{}:beginBusy(b);try{
 if(b.id==='theme-toggle'){window.relayTheme?.set(document.documentElement.dataset.theme==='dark'?'light':'dark');syncTheme();return;}
 if(b.hasAttribute('data-billing-updated')){if(confirm('Have you added credits to the connected OpenAI project?'))await action('/api/openai/control',{billingUpdated:true});return;}
 if(b.id==='notification-toggle'){$('#notification-panel').hidden=!$('#notification-panel').hidden;b.setAttribute('aria-expanded',String(!$('#notification-panel').hidden));if(!$('#notification-panel').hidden)await refreshNotifications();return;}
 if(b.id==='notifications-read-all'){notificationData=await api('/api/notifications/read',{all:true});renderNotifications();return;}
 if(b.dataset.notification){const item=notificationData.items.find(n=>n.id===b.dataset.notification);if(!item)return;notificationData=await api('/api/notifications/read',{id:item.id});renderNotifications();$('#notification-panel').hidden=true;$('#notification-toggle').setAttribute('aria-expanded','false');await switchProduct(item.product_id||'');if((item.product_id||'')!==selectedProduct){toast('This product workspace is archived.');return;}await openProspect(item.lead_id,item.draft_id);if(item.kind!=='followup_ready'){const summary=[...$('#modal-content').querySelectorAll('summary')].find(s=>s.textContent==='Email history');if(summary)summary.parentElement.open=true;}return;}
 if(b.dataset.productNew!==undefined){productForm();return;}
 if(b.dataset.productEdit){openModal('<div role="status" aria-busy="true">Loading product…</div>');const seq=modalRequest,workspace=selectedProduct;try{const detail=await api('/api/products/'+b.dataset.productEdit);if(seq===modalRequest&&workspace===selectedProduct&&$('#modal').open)productForm(detail.product);}catch(error){if(seq!==modalRequest||workspace!==selectedProduct||!$('#modal').open)return;openModal('<h2>Product unavailable</h2><p>'+esc(error.message)+'</p><button data-product-edit="'+esc(b.dataset.productEdit)+'">Try again</button>');throw error;}return;}
 if(b.dataset.productOpen){await switchProduct(b.dataset.productOpen,'prospects');return;}
 if(b.dataset.productResearch){await switchProduct(b.dataset.productResearch,'products');return;}
 if(b.dataset.productSender){const r=await api('/api/products/'+b.dataset.productSender+'/sender',{});toast(r.accepted?'Sender is authorized in the connected Gmail mailbox.':r.message);return;}
 if(b.hasAttribute('data-reload')){await load();return;}
 if(workspaceUnavailable&&(b.dataset.view||b.dataset.go)){await load();return;}
 if(b.dataset.view||b.dataset.go){await navigate(b.dataset.view||b.dataset.go);return;}
 if(b.dataset.group){dashboardGroup=b.dataset.group;await showPage();return;}
 if(b.dataset.page!==undefined){await showPage(Number(b.dataset.page));return;}
 if(b.hasAttribute('data-stop-search')){await action('/api/discovery/stop',{cycleId:b.dataset.stopSearch||undefined},'Search stopped');return;}
 if(b.dataset.deleteProspect){const row=pageData.rows.find(l=>l.id===b.dataset.deleteProspect);if(!confirm('Delete '+(row?.company||'this prospect')+'? Pending emails will be cancelled.'))return;await action('/api/prospects/'+encodeURIComponent(b.dataset.deleteProspect)+'/delete',{},'Prospect deleted');return;}
 if(b.dataset.open){await openProspect(b.dataset.open,b.dataset.email);return;}
 if(b.id==='close-modal'){modalRequest++;$('#modal').close();modalDraft=null;return;}
 if(b.id==='refresh'){await load();return;}
 if(b.id==='logout'){await api('/api/logout',{});data=null;notificationData={items:[],unread:0};renderNotifications();$('#notification-panel').hidden=true;workspaceUnavailable=false,snapshotMode=null,lastSavedRefresh=0;$('#app').hidden=true;$('#login').hidden=false;return;}
 if(b.dataset.action==='import'){importModal();return;}
 if(b.dataset.action==='discover'){
  const target=requestedTarget();b.disabled=true;await saveLocations();await action('/api/discover',{target},'Searching…');return;
 }
 if(b.dataset.productFind){const target=requestedTarget();await switchProduct(b.dataset.productFind,'prospects');await action('/api/discover',{target},'Searching…');return;}

 b.disabled=true;
 if(b.dataset.send){const d=detailData.drafts.find(x=>x.id===b.dataset.send);const version=await saveEmail(d);const result=await api(`/api/drafts/${d.id}/approve`,{version,evidenceReviewed:true,contactReviewed:true});toast(result.message);await load();if(result.status==='sent'){$('#modal').close();modalDraft=null;}else await openProspect(d.lead_id,d.id);}
 if(b.dataset.reject){const d=detailData.drafts.find(x=>x.id===b.dataset.reject);await action(`/api/drafts/${d.id}/reject`,{version:d.version},'Email discarded');$('#modal').close();modalDraft=null;}
 if(b.dataset.rewrite){const d=detailData.drafts.find(x=>x.id===b.dataset.rewrite);await action(`/api/drafts/${d.id}/rewrite`,{version:d.version},'Improving this email in the background.');$('#modal').close();modalDraft=null;}
 if(b.dataset.suppress){await action(`/api/leads/${b.dataset.suppress}/suppress`,{},'Contact stopped');$('#modal').close();}
 if(b.dataset.reconcile){await action(`/api/drafts/${b.dataset.reconcile}/reconcile`,{},'Delivery checked');await openProspect(detailData.lead.id,b.dataset.reconcile);}
 if(b.dataset.action==='tick')await action('/api/tick',{},'Background tasks completed');
 if(b.dataset.action==='notify')await action('/api/notify',{},'Status update requested');
 if(b.dataset.action==='check'){const result=await api('/api/connections/check',{});$('#connection-results').innerHTML=Object.entries(result).map(([k,v])=>`<p>${esc(k)}: ${esc(v)}</p>`).join('');}
 if(b.dataset.retry)await action(`/api/jobs/${b.dataset.retry}/retry`,{confirmPaidRetry:true},'Retry queued');
 }catch(error){toast(error.message);}finally{done();}
});
document.addEventListener('input',e=>{if(e.target.name==='body'&&e.target.closest('#draft-form')&&emailPreview){renderEmailPreview(emailPreview,e.target.value.trim()+'\n\n'+(emailPreview.senderName||data.settings.senderName));return;}if(e.target.name==='searchTarget'){requestedCount=e.target.value;return;}if(e.target.id==='search'){filter=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{try{if(await fetchPage()){pageLoading=false;const cursor=$('#search')?.selectionStart;render();$('#search')?.focus();$('#search')?.setSelectionRange(cursor,cursor);}}catch(err){toast(err.message);}},220);}});
document.addEventListener('change',async e=>{if(e.target.id==='theme-preference'){window.relayTheme?.set(e.target.value);syncTheme();return;}if(e.target.id==='country-filter'){locationSelection=e.target.value==='saved'?(locationSelection||data.settings.locationIds):[e.target.value||'worldwide'];e.target.closest('.location-filters').outerHTML=locationPicker();$('#country-filter')?.focus();return;}if(e.target.id==='place-filter'){locationSelection=chosenLocations();return;}if(e.target.id==='status-filter'){statusFilter=e.target.value;try{await showPage();}catch(err){toast(err.message);}}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button[type=submit]');if(form.dataset.submitting||(button&&pendingButtons.has(buttonKey(button))))return;form.dataset.submitting='true';const done=beginBusy(button);try{
 if(form.id==='product-form'){const f=new FormData(form),payload={name:String(f.get('name')),website:String(f.get('website')),description:String(f.get('description')),remarks:String(f.get('remarks')),sender_email:String(f.get('sender_email')),customerTypes:f.getAll('customerTypes'),customerDescription:String(f.get('customerDescription')),customerComments:String(f.get('customerComments')),revision:Number(form.dataset.revision)};const files=[...form.querySelector('[name=screenshots]').files];if(files.length){if(files.length>3||files.some(f=>f.size>512000))throw new Error('Choose up to three screenshots, each at most 500 KB');payload.images=await Promise.all(files.map(async file=>({name:file.name,data:await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);})})));}else if(f.has('clearImages'))payload.images=[];const result=await api('/api/products'+(form.dataset.id?'/'+form.dataset.id:''),payload);$('#modal').close();await switchProduct(result.product.id,'products');toast('Product saved.');return;}
 if(form.id==='login-form'){await api('/api/login',{password:$('#password').value});$('#password').value='';$('#login-error').textContent='';view='prospects';await load();}
 if(form.id==='draft-form'){const d=detailData.drafts.find(x=>x.id===form.dataset.id);await saveEmail(d);toast('Email saved');await openProspect(d.lead_id,d.id);await load();}
 if(form.id==='lead-form'){const f=new FormData(form);await action(`/api/leads/${form.dataset.id}/update`,{...Object.fromEntries(f),verification:f.has('manual')?'manual':'unchanged'},'Contact saved');await openProspect(form.dataset.id,modalDraft);}
 if(form.id==='import-form'){const r=await action('/api/import',{leads:JSON.parse(form.elements.namedItem('records').value)});toast(`${r.added} added, ${r.duplicates} duplicates, ${r.errors.length} errors`);if(!r.errors.length)$('#modal').close();}
 if(form.id==='sender-form'){const f=new FormData(form);await action('/api/settings/sender',{senderName:String(f.get('senderName')),businessAddress:data.settings.businessAddress||'',...(selectedProduct?{senderEmail:String(f.get('senderEmail'))}:{})},'Sender details saved');$('#sender-save-status').textContent='Saved.';}
 if(form.id==='locations-form'){await saveLocations();toast('Locations saved.');await load();}
 if(form.id==='settings-form'){const f=new FormData(form),s={...data.settings};for(const k of ['openaiBudget','apifyBudget','apifyRunCap','discoveryResults','sendStartHour','sendEndHour'])s[k]=Number(f.get(k));s.allowWorkEmailEnrichment=f.has('allowWorkEmailEnrichment');s.discoveryProvider=String(f.get('discoveryProvider')||'openai');s.customerTypes=f.getAll('customerTypes');for(const k of ['offerContext','freeOffer','portfolio','customerDescription','customerComments'])s[k]=String(f.get(k));s.followupDays=String(f.get('followupDays')).split(',').map(x=>x.trim()).filter(Boolean).map(Number);s.sendWeekends=f.has('sendWeekends');s.providerPolicyConfirmed=f.has('providerPolicyConfirmed');await action('/api/settings/preferences',s,'Preferences saved');}
 }catch(err){if(form.id==='login-form')$('#login-error').textContent=err.message;else toast(err.message);}finally{delete form.dataset.submitting;done();}
});
load().catch(e=>{if(!e.message.includes('Sign in'))$('#login-error').textContent=e.message;});
let refreshing=false;
setInterval(()=>{if(data&&!document.hidden)refreshNotifications();},30000);
let lastWorkspacePoll=0;
setInterval(async()=>{const interval=data?.metrics?.campaign?.canStop?10000:60000;if(Date.now()-lastWorkspacePoll<interval||refreshing||!data||(snapshotMode&&Date.now()-lastSavedRefresh<300000)||document.hidden||view==='settings'||document.activeElement?.matches('input,textarea,select'))return;lastWorkspacePoll=Date.now();refreshing=true;try{await load();}catch{}finally{refreshing=false;}},10000);


async function switchProduct(id,nextView='prospects'){selectedProduct=id||'';sessionStorage.setItem('relay-product',selectedProduct);snapshotMode=null;locationSelection=null;detailData=null;modalDraft=null;productDetailData=null;pageLoading=false;pageRequest++;modalRequest++;pageData={rows:[],counts:{},total:0,offset:0,hasMore:false};view=nextView;data=null;$('#content').innerHTML='<div class="empty" role="status" aria-busy="true">Loading workspace…</div>';if($('#modal').open)$('#modal').close();await load();}
function renderProductSwitch(){
 const select=$('#product-switch');if(select)select.innerHTML='<option value="">Existing outreach</option>'+products.map(p=>`<option value="${esc(p.id)}" ${p.id===selectedProduct?'selected':''}>${esc(p.name)}</option>`).join('');
 if(select)select.value=selectedProduct;
 if(selectedProduct){const p=products.find(p=>p.id===selectedProduct);$('#breadcrumb').textContent=(p?.name||'Product')+' / '+({products:'Products',prospects:'Prospects',dashboard:'Dashboard',settings:'Settings'}[view]);}
}
function productsPage(){
 const cards=products.filter(p=>p.id!==selectedProduct).map(p=>`<article class="panel product-card"><h2>${esc(p.name)}</h2><p>${esc(p.website)}</p>${pill(p.state)}<div class="actions spaced"><button data-product-research="${p.id}">Details</button><button data-product-open="${p.id}">Prospects</button></div></article>`).join('');
 let detail=selectedProduct&&productDetailData?.error?'<div class="note error" role="alert">'+esc(productDetailData.error)+' <button data-go="products">Try again</button></div>':selectedProduct&&!productDetailData?'<div class="empty" role="status" aria-busy="true">Loading product…</div>':'';
 const x=productDetailData;if(selectedProduct&&x?.product?.id===selectedProduct){const p=x.product,a=x.analysis||{};
 detail=`<section class="panel product-research"><h2>${esc(p.name)}</h2><p><a href="${safeLink(p.website)}" target="_blank" rel="noopener">${esc(p.website)}</a> · ${pill(p.state)}</p><div class="actions"><button data-product-edit="${p.id}">Edit product</button>${countInput()}<button class="primary" data-product-find="${p.id}">Search prospects</button></div><details class="spaced"><summary>Product details</summary><p>${esc(p.description)}</p>${p.remarks?`<h3>Instructions</h3><p>${esc(p.remarks)}</p>`:''}<p>Sender: ${esc(p.sender_email)} <button data-product-sender="${p.id}">Check sender</button></p><div class="product-images">${(x.images||[]).map(i=>`<img src="${i.data}" alt="${esc(i.name)}">`).join('')}</div></details>${a.productSummary?`<details class="spaced"><summary>Customer profile</summary><p>${esc(a.productSummary)}</p><h3>Target customers</h3>${listHtml(a.targetCustomers)}<p>${esc(a.targetingRationale)}</p><h3>Use cases</h3>${(a.useCases||[]).map(c=>`<p><strong>${esc(c.buyerRole)}</strong>: ${esc(c.workflow)}</p>`).join('')}<h3>Exclusions</h3>${listHtml(a.exclusions)}<details><summary>Research details</summary><h3>Qualification</h3>${listHtml(a.qualificationCriteria)}<h3>Unknowns</h3>${listHtml(a.unknowns)}<h3>Email guidance</h3><p>${esc(a.emailGuidance)}</p><h3>Sources</h3>${(a.sources||[]).map(v=>`<p><a href="${safeLink(v.url)}" target="_blank" rel="noopener">${esc(v.observation||v.url)}</a></p>`).join('')}</details></details>`:''}</section>`;
 }
 return title('Products','', '<button class="primary" data-product-new>Add product</button>')+detail+'<div class="product-grid">'+(cards||(!selectedProduct?empty('Add your first product','Then search for prospects.'):''))+'</div>';
}

function listHtml(items){return (items||[]).length?'<ul>'+items.map(v=>'<li>'+esc(v)+'</li>').join('')+'</ul>':'<p class="quiet">None recorded</p>';}
function productForm(p){openModal(`<h2>${p?'Edit':'Add'} product</h2><form id="product-form" data-id="${esc(p?.id||'')}" data-revision="${p?.revision||0}"><label>Product name<input name="name" value="${esc(p?.name||'')}" required maxlength="120"></label><label>Product website<input name="website" type="url" value="${esc(p?.website||'')}" required></label><label>Product description<textarea name="description" rows="5" maxlength="12000" required>${esc(p?.description||'')}</textarea></label><label>Instructions (optional)<textarea name="remarks" rows="5" maxlength="12000" placeholder="What customers to find or exclude, geography, product points and email instructions">${esc(p?.remarks||'')}</textarea></label><details open><summary>Customer targeting</summary>${customerFields(p||{})}</details><label>Sender email<input name="sender_email" type="email" value="${esc(p?.sender_email||data.connections.sender||'')}" required></label><label>Screenshots (optional)<input name="screenshots" type="file" accept="image/png,image/jpeg,image/webp" multiple></label><p class="quiet">Up to 3 images, 500 KB each.</p>${p?'<label class="checkbox"><input name="clearImages" type="checkbox">Remove saved screenshots if no replacements are selected</label>':''}<button type="submit" class="primary">Save product</button></form>`);}
document.addEventListener('change',async e=>{if(e.target.id==='product-switch'){try{await switchProduct(e.target.value,view);}catch(error){toast(error.message);}}});

document.addEventListener('pointerdown',e=>{if(!e.target.closest('.location-filters')&&document.activeElement?.matches('.location-filters select'))document.activeElement.blur();});
